code_sketch:
struct handler { int fd; void (*on_ready)(struct handler *self, uint32_t events); };

for (;;) {
    int n = epoll_wait(epfd, evs, MAX_EVENTS, -1);          /* demultiplex */
    if (n < 0) { if (errno == EINTR) continue; perror("epoll_wait"); break; }
    for (int i = 0; i < n; i++) {
        struct handler *h = table[evs[i].data.fd];
        rearm(epfd, h->fd);                                /* one-shot: re-arm before dispatch */
        h->on_ready(h, evs[i].events);                     /* dispatch to the handler */
    }
}

