struct event_base *base = event_base_new();          /* picks the fastest backend */
struct event *ev = event_new(base, fd, EV_READ | EV_PERSIST, on_readable, session);
event_add(ev, NULL);                                  /* register handler for the handle */
event_base_dispatch(base);                            /* the dispatch loop */
